// app/api/enquiry/route.ts on your website. It runs on the server, so the key stays secret.
// Your form posts to /api/enquiry; this sends the enquiry on to the CRM.
export async function POST(request: Request) {
  const form = await request.json();
  // One ID per submission. Send the same one again if you retry, and the CRM captures it once.
  const submissionId = form.submissionId ?? crypto.randomUUID();

  const response = await fetch("https://app.marro.si/api/v1/leads/capture", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.CRM_API_KEY}`,
      "Content-Type": "application/json",
      "Idempotency-Key": submissionId,
    },
    body: JSON.stringify({
      name: form.name,
      phone: form.phone,
      email: form.email,
      source: "Website",
      fields: {
        "city": form.city,
        "interest": form.interest,
      },
      attribution: {
        pageUrl: form.pageUrl,
        referrer: form.referrer,
        formName: "Contact form",
      },
    }),
    signal: AbortSignal.timeout(10_000),
  });

  if (!response.ok) {
    // Keep the enquiry (a sheet, a database row, an email) and retry later with the same
    // submissionId, so no lead is lost while the CRM cannot be reached.
    console.error("CRM capture failed", response.status, await response.text());
  }
  return Response.json({ ok: true });
}

